"""BQ-20: records that are not a known immutable declaration behave exactly as at the handoff snapshot.

For every (adapter id, version, operation) in {24 catalog ids, an unknown id, '' and None} x {'1', '2'} x {catalog operation, 'bogus'}:
claim_media(collect), mark_media_uncertain, _media_artifact_for (two MIME values), _media_result_for (the recording_bundle read path) and
MediaCoordinator._reconcile give the outcomes below. SNAPSHOT_TABLE was produced by running the same probes against the snapshot files
(src/bg_jobs.py, src/openclank/media_jobs.py and media_adapters/base.py of refs/snapshots/handoff-2026-11-09 loaded in place of the tree
modules in the sandbox); the claim column only records whether an owned-fetch lifetime marker was written (its label is neutral now).
"""
import asyncio
import hashlib
import json

import contextlib
from src import bg_jobs as bj
from src.openclank.media_adapters import base
from src.openclank.media_jobs import MediaCoordinator
ACCT = 'acct'
def H(c): return hashlib.sha256(c.encode()).hexdigest()
@contextlib.contextmanager
def _nolock(): yield
def with_store(rows, fn):
    old = (bj._store_lock, bj._load, bj._save)
    bj._store_lock, bj._load, bj._save = _nolock, (lambda: rows), (lambda jobs: None)
    try: return fn()
    finally: bj._store_lock, bj._load, bj._save = old
def outcome(fn, *a, **k):
    try: r = fn(*a, **k)
    except Exception as e: return f'{type(e).__name__}: {e}'
    return r
def norm(r):
    if isinstance(r, dict): return 'dict'
    return 'ok' if r is True else r
IDS = [n for n, _ in base._MEDIA_OPERATION_FACTS] + ['no-such-adapter', '', None]
OPS = {n: f.operation for n, f in base._MEDIA_OPERATION_FACTS}
def ident(a, v, op): return {'adapter_id': a, 'adapter_version': v, 'operation': op, 'account_id': ACCT}
def art(a, mime):
    d = {'artifact_id': 'art', 'sha256': H('a'), 'mime_type': mime, 'size': 1}
    if a == 'comfyui-flac-v1': d['audio'] = {'sampleRate': 44100, 'channels': 2, 'bitsPerSample': 16, 'declaredSamples': 1000, 'payloadVerified': False}
    if a == 'sprixen-animation-v1': d['animation'] = {'animationID': 'anim_x', 'type': 'idle', 'frameCount': 4, 'fps': 12, 'width': 64, 'height': 64, 'sha256': H('a')}
    if a in ('blender-glb-four-heading-v1', 'blender-glb-rig-clip-v1', 'sprite-sheet-v1', 'sprite-sheet-crops-v1'): d['layout'] = {}
    return d
def claim(i):
    rec = {'id': 'j1', 'kind': 'media', 'version': 1, 'account_id': ACCT, 'revision': 1, 'status': 'collecting', 'claim': None, 'artifact': None, 'identity': i}
    r = outcome(lambda: with_store({'j1': rec}, lambda: bj.claim_media('j1', account_id=ACCT, revision=1, action='collect')))
    return ('LABEL:' + str(r['record']['claim'].get('owned_lifetime') is not None)) if isinstance(r, dict) else r
def mark(i):
    rec = {'id': 'j1', 'kind': 'media', 'version': 1, 'account_id': ACCT, 'revision': 1, 'status': 'collecting', 'claim': {'action': 'collect', 'token': 't'}, 'identity': i}
    return norm(outcome(lambda: with_store({'j1': rec}, lambda: bj.mark_media_uncertain('j1', account_id=ACCT, revision=1))))
def artifact(i, mime):
    rec = {'identity': dict(i, resource_binding={'animationParameters': {'type': 'idle', 'frameCount': 4, 'fps': 12}}), 'remote_task_id': 'anim_x'}
    return norm(outcome(bj._media_artifact_for, rec, art(i['adapter_id'], mime)))
def result(i):
    a = art(i['adapter_id'], 'image/png')
    rec = {'identity': dict(i, resource_binding={'animationParameters': {'type': 'idle', 'frameCount': 4, 'fps': 12}}), 'remote_task_id': 'anim_x', 'artifact': a}
    val = {'operation_id': 'op', 'item_id': 'output', 'resource_ref': 'r', 'sha256': a['sha256'], 'mime_type': 'image/png'}
    for k in ('audio', 'animation', 'layout'):
        if k in a: val[k] = a[k]
    return norm(outcome(bj._media_result_for, rec, val, 'op'))
def reconcile(i):
    job = {'identity': i, 'chat_detached': False, 'status': 'running', 'revision': 1, 'claim': {'action': 'collect'}}
    c = object.__new__(MediaCoordinator)
    async def scope(identity, control=False): return True
    async def read(identity, job_id): return job
    async def owned(identity, op): return None
    c._scope, c._read, c._owned = scope, read, owned
    return outcome(lambda: asyncio.run(c._reconcile(i, 'j'))['status'])
def build_table():
    table = {}
    for a in IDS:
        for v in ('1', '2'):
            for op in (OPS.get(a, 'x'), 'bogus'):
                i = ident(a, v, op)
                mime = base.media_operation_facts(a, '1').mime_type if base.media_operation_facts(a, '1') else 'image/png'
                table['%s|%s|%s' % (a, v, op)] = [claim(i), mark(i), artifact(i, 'image/png'), artifact(i, mime), result(i), reconcile(i)]
    return table


