def test_every_probe_equals_the_snapshot():
    now = build_table()
    assert len(now) == len(SNAPSHOT_TABLE) == 108
    diff = {k: (SNAPSHOT_TABLE[k], now[k]) for k in SNAPSHOT_TABLE if SNAPSHOT_TABLE[k] != now[k]}
    assert not diff, diff
